"""Migration of legacy ACCT_MASTER rows to modern account records."""


def convert_account(row: dict) -> dict | None:
    """Convert one legacy ACCT_MASTER row to an account record."""
    def value(column: str) -> str:
        return row.get(column, "")

    if value("DEL_FLG") == "Y":
        return None

    def amount(column: str) -> float:
        raw = value(column)
        return 0.0 if raw == "" else float(raw)

    def date(column: str) -> str | None:
        raw = value(column)
        if raw in ("", "00000000"):
            return None
        return f"{raw[:4]}-{raw[4:6]}-{raw[6:8]}"

    return {
        "account_id": value("ACCT_ID"),
        "name": value("ACCT_NM"),
        "account_type": value("ACCT_TYP"),
        "sic_code": value("SIC_CD"),
        "region": value("REGION_CD"),
        "annual_revenue": amount("ANN_REV"),
        "currency": value("CURR_CD") or "USD",
        "owner_id": value("OWNER_UID"),
        "team_code": value("TEAM_CD"),
        "credit_limit": amount("CRED_LIMIT"),
        "credit_hold": value("CRED_HOLD") == "Y",
        "created_date": date("CREATE_DT"),
        "updated_date": date("UPD_DT"),
    }
